import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Legend, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { AlertTriangle, ArrowDownRight, ArrowUpRight, Banknote, CalendarDays, ChartNoAxesCombined, CircleDollarSign, CirclePlus, CreditCard, Download, Landmark, Lightbulb, Loader2, MoreHorizontal, Pencil, Plus, ReceiptText, Scale, Search, ShieldCheck, Sparkles, Target, Trash2, TrendingUp, WalletCards } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

export type FinanceSection = "dashboard" | "transactions" | "budgets" | "projections" | "goals" | "cards" | "debts" | "assets" | "calendar" | "reports" | "settings";

const money = (cents?: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format((cents ?? 0) / 100);
const compactMoney = (cents?: number) => new Intl.NumberFormat("pt-BR", { notation: "compact", style: "currency", currency: "BRL", maximumFractionDigits: 1 }).format((cents ?? 0) / 100);
const inputMoney = (cents?: number) => ((cents ?? 0) / 100).toFixed(2);
const centsFromInput = (value: string) => Math.round((Number(value.replace(",", ".")) || 0) * 100);
const shortDate = (date?: Date | string | null) => date ? new Date(date).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }).replace(".", "") : "—";
const dateInput = (date?: Date | string | null) => date ? new Date(date).toISOString().slice(0, 10) : "";
const todayInput = () => new Date().toISOString().slice(0, 10);
const statusLabel: Record<string, string> = { paid: "Pago", pending: "Pendente", overdue: "Em atraso", open: "Aberta", closed: "Fechada", active: "Ativa", completed: "Concluída", paused: "Pausada" };

function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <section className={`glass-card hairline-corner rounded-[1.5rem] ${className}`}>{children}</section>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between mb-7">
    <div className="max-w-2xl">
      <p className="text-[10px] font-extrabold uppercase tracking-[0.22em] text-primary">{eyebrow}</p>
      <h1 className="editorial-title mt-2 text-4xl leading-none tracking-tight sm:text-5xl">{title}</h1>
      <p className="mt-3 text-sm leading-6 text-muted-foreground">{description}</p>
    </div>
    {action}
  </div>;
}

function Metric({ label, value, note, kind = "neutral", icon: Icon }: { label: string; value: string; note: string; kind?: "positive" | "negative" | "neutral"; icon: React.ElementType }) {
  const tone = kind === "positive" ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-400/15 dark:text-emerald-300" : kind === "negative" ? "bg-rose-100 text-rose-700 dark:bg-rose-400/15 dark:text-rose-300" : "bg-primary/10 text-primary";
  return <Panel className="p-5 overflow-hidden"><div className="flex items-start justify-between gap-3"><div><p className="text-[11px] uppercase tracking-[0.15em] font-bold text-muted-foreground">{label}</p><p className="editorial-title mt-3 text-3xl tracking-tight">{value}</p></div><span className={`grid h-10 w-10 place-items-center rounded-2xl ${tone}`}><Icon className="h-4 w-4" /></span></div><p className="mt-3 text-xs text-muted-foreground">{note}</p></Panel>;
}

function EmptyState({ onDemo, onOpenSettings }: { onDemo: () => void; onOpenSettings: () => void }) {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const seedDemo = trpc.finance.seedDemo.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setLocation("/"); toast.success("Demonstração integrada carregada."); }, onError: error => toast.error(error.message) });
  return <Panel className="overflow-hidden p-7 sm:p-10"><div className="grid gap-8 lg:grid-cols-[1.1fr_.9fr] lg:items-center"><div><p className="text-[10px] font-extrabold uppercase tracking-[.24em] text-primary">Seu ponto de partida</p><h2 className="editorial-title mt-3 max-w-lg text-4xl leading-tight">Tudo fica mais claro quando há um primeiro movimento.</h2><p className="mt-4 max-w-xl text-sm leading-6 text-muted-foreground">Comece adicionando sua renda e uma conta. Se preferir explorar antes, carregue uma demonstração conectada aos mesmos cálculos e telas da aplicação.</p><div className="mt-7 flex flex-wrap gap-3"><Button onClick={() => setLocation("/configuracoes")} className="rounded-xl"><CirclePlus className="mr-2 h-4 w-4" />Configurar perfil</Button><Button variant="outline" onClick={() => seedDemo.mutate()} disabled={seedDemo.isPending} className="rounded-xl bg-card/60"><Sparkles className="mr-2 h-4 w-4" />{seedDemo.isPending ? "Carregando…" : "Explorar demonstração"}</Button></div></div><div className="relative rounded-[1.5rem] border border-primary/15 bg-gradient-to-br from-primary/15 via-rose-100/60 to-emerald-100/60 p-6 dark:from-primary/25 dark:via-rose-900/20 dark:to-emerald-900/20"><div className="absolute right-6 top-0 h-14 border-l border-primary/30" /><div className="rounded-2xl bg-card/80 p-5 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-bold uppercase tracking-[.18em] text-muted-foreground">Primeira visão</span><ShieldCheck className="h-4 w-4 text-emerald-600" /></div><p className="editorial-title mt-7 text-3xl">Organizar. Projetar. Evoluir.</p><div className="mt-6 space-y-3"><div className="h-2.5 w-[76%] rounded-full bg-primary/30" /><div className="h-2.5 w-[56%] rounded-full bg-emerald-300/70" /><div className="h-2.5 w-[68%] rounded-full bg-rose-200" /></div></div></div></div></Panel>;
}

function TransactionDialog({ dashboard, transaction, onDone }: { dashboard: any; transaction?: any; onDone: () => void }) {
  const [open, setOpen] = useState(false);
  const [type, setType] = useState<"income" | "expense">(transaction?.type ?? "expense");
  const [description, setDescription] = useState(transaction?.description ?? "");
  const [amount, setAmount] = useState(inputMoney(transaction?.amountCents));
  const [accountId, setAccountId] = useState(transaction?.accountId ? String(transaction.accountId) : "none");
  const [categoryId, setCategoryId] = useState(transaction?.categoryId ? String(transaction.categoryId) : "none");
  const [occurredAt, setOccurredAt] = useState(dateInput(transaction?.occurredAt) || todayInput());
  const [dueAt, setDueAt] = useState(dateInput(transaction?.dueAt));
  const [paymentStatus, setPaymentStatus] = useState(transaction?.paymentStatus ?? "paid");
  const [notes, setNotes] = useState(transaction?.notes ?? "");
  const utils = trpc.useUtils();
  const create = trpc.finance.transactions.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); onDone(); setOpen(false); toast.success("Lançamento registrado."); }, onError: error => toast.error(error.message) });
  const update = trpc.finance.transactions.update.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); onDone(); setOpen(false); toast.success("Lançamento atualizado."); }, onError: error => toast.error(error.message) });
  const matchingCategories = dashboard?.categories?.filter((item: any) => item.type === type) ?? [];
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!description.trim() || centsFromInput(amount) <= 0) { toast.error("Informe uma descrição e um valor válido."); return; }
    const values = { accountId: accountId === "none" ? null : Number(accountId), categoryId: categoryId === "none" ? null : Number(categoryId), description: description.trim(), type, amountCents: centsFromInput(amount), occurredAt: new Date(`${occurredAt}T12:00:00`), dueAt: dueAt ? new Date(`${dueAt}T12:00:00`) : null, paymentStatus: paymentStatus as "paid" | "pending" | "overdue", paymentMethod: null, notes: notes.trim() || null };
    if (transaction) update.mutate({ id: transaction.id, ...values }); else create.mutate(values);
  };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />{transaction ? "Editar" : "Novo lançamento"}</Button></DialogTrigger><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-xl"><form onSubmit={submit}><DialogHeader><DialogTitle className="editorial-title text-3xl">{transaction ? "Editar lançamento" : "Novo lançamento"}</DialogTitle><DialogDescription>Registre um movimento. Os indicadores, saldos e projeções serão atualizados.</DialogDescription></DialogHeader><div className="grid gap-4 py-6 sm:grid-cols-2"><div className="grid gap-2"><Label>Tipo</Label><Select value={type} onValueChange={value => { setType(value as "income" | "expense"); setCategoryId("none"); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="income">Receita</SelectItem><SelectItem value="expense">Despesa</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Valor (R$)</Label><Input type="number" min="0" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} /></div><div className="grid gap-2 sm:col-span-2"><Label>Descrição</Label><Input value={description} onChange={event => setDescription(event.target.value)} placeholder="Ex.: Mercado da semana" /></div><div className="grid gap-2"><Label>Conta</Label><Select value={accountId} onValueChange={setAccountId}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent><SelectItem value="none">Sem conta vinculada</SelectItem>{dashboard?.accounts?.map((account: any) => <SelectItem key={account.id} value={String(account.id)}>{account.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Categoria</Label><Select value={categoryId} onValueChange={setCategoryId}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent><SelectItem value="none">Sem categoria</SelectItem>{matchingCategories.map((category: any) => <SelectItem key={category.id} value={String(category.id)}>{category.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Data</Label><Input type="date" value={occurredAt} onChange={event => setOccurredAt(event.target.value)} /></div><div className="grid gap-2"><Label>Status</Label><Select value={paymentStatus} onValueChange={setPaymentStatus}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="paid">Pago</SelectItem><SelectItem value="pending">Pendente</SelectItem><SelectItem value="overdue">Em atraso</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Vencimento</Label><Input type="date" value={dueAt} onChange={event => setDueAt(event.target.value)} /></div><div className="grid gap-2 sm:col-span-2"><Label>Observações</Label><Textarea value={notes} onChange={event => setNotes(event.target.value)} placeholder="Opcional" /></div></div><DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button type="submit" disabled={create.isPending || update.isPending}>{(create.isPending || update.isPending) && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}{transaction ? "Salvar alterações" : "Adicionar lançamento"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function DashboardPage({ dashboard, onDemo, onOpenSettings }: { dashboard: any; onDemo: () => void; onOpenSettings: () => void }) {
  const hasData = dashboard.accounts.length + dashboard.transactions.length + dashboard.goals.length > 0;
  if (!hasData) return <><PageHeading eyebrow="Sua área privada" title="Bem-vindo à Clareza." description="Construa uma visão organizada do presente e acompanhe os reflexos de cada decisão no seu futuro financeiro." /><EmptyState onDemo={onDemo} onOpenSettings={onOpenSettings} /></>;
  const { summary } = dashboard;
  const emergencyStatus = summary.emergencyMonths >= 6 ? "Protegida" : summary.emergencyMonths >= 3 ? "Em atenção" : "A construir";
  return <div><PageHeading eyebrow="Visão geral" title="Uma leitura calma do seu dinheiro." description="Os números abaixo são atualizados a partir dos lançamentos, contas, cartões, dívidas e metas cadastrados." action={<TransactionDialog dashboard={dashboard} onDone={() => undefined} />} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Saldo disponível" value={money(summary.balanceCents)} note="Somatório das suas contas" icon={WalletCards} /><Metric label="Receitas no mês" value={money(summary.monthIncomeCents)} note="Entradas registradas no período" kind="positive" icon={ArrowUpRight} /><Metric label="Despesas no mês" value={money(summary.monthExpensesCents)} note={`${summary.savingsRate}% de taxa de economia`} kind="negative" icon={ArrowDownRight} /><Metric label="Patrimônio líquido" value={money(summary.netWorthCents)} note="Ativos menos passivos" icon={Scale} /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_.95fr]"><Panel className="p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Fluxo de caixa</p><h2 className="editorial-title mt-2 text-2xl">Receitas e despesas</h2></div><Badge variant="outline" className="border-primary/20 bg-primary/5 text-primary">Últimos 6 meses</Badge></div><div className="mt-6 h-[260px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={dashboard.cashflow} barGap={6}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="currentColor" opacity={.09} /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><YAxis hide /><Tooltip formatter={(value: number) => money(value)} cursor={{ fill: "transparent" }} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Bar dataKey="receitas" fill="#6da985" radius={[7, 7, 0, 0]} /><Bar dataKey="despesas" fill="#c7869d" radius={[7, 7, 0, 0]} /></BarChart></ResponsiveContainer></div></Panel><Panel className="p-5 sm:p-6"><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Segurança financeira</p><h2 className="editorial-title mt-2 text-2xl">Sua reserva</h2><div className="mt-7 rounded-2xl bg-emerald-100/65 p-5 dark:bg-emerald-400/10"><p className="editorial-title text-4xl text-emerald-800 dark:text-emerald-200">{summary.emergencyMonths.toLocaleString("pt-BR")} meses</p><p className="mt-2 text-sm text-emerald-800/75 dark:text-emerald-100/75">Cobertura de despesas essenciais</p></div><div className="mt-5 flex items-center justify-between text-sm"><span className="text-muted-foreground">Status</span><span className="font-bold text-foreground">{emergencyStatus}</span></div><Progress className="mt-2 h-2" value={Math.min(summary.emergencyMonths / 6 * 100, 100)} /></Panel></div><div className="mt-5 grid gap-5 xl:grid-cols-[.95fr_1.05fr_1fr]"><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Onde vai</p><h2 className="editorial-title mt-2 text-2xl">Gastos do mês</h2></div><CircleDollarSign className="h-5 w-5 text-primary" /></div>{dashboard.categorySpend.length ? <><div className="mt-4 h-[150px]"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={dashboard.categorySpend} dataKey="amountCents" nameKey="name" innerRadius={44} outerRadius={64} paddingAngle={4}>{dashboard.categorySpend.map((item: any) => <Cell key={item.categoryId} fill={item.color} />)}</Pie><Tooltip formatter={(value: number) => money(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /></PieChart></ResponsiveContainer></div><div className="space-y-2">{dashboard.categorySpend.slice(0, 3).map((item: any) => <div key={item.categoryId} className="flex items-center justify-between text-xs"><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full" style={{ backgroundColor: item.color }} />{item.name}</span><span className="font-bold">{money(item.amountCents)}</span></div>)}</div></> : <p className="mt-8 text-sm text-muted-foreground">Seus gastos por categoria aparecerão aqui.</p>}</Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Próximos dias</p><h2 className="editorial-title mt-2 text-2xl">Compromissos</h2></div><CalendarDays className="h-5 w-5 text-primary" /></div><div className="mt-5 space-y-2">{dashboard.upcoming.length ? dashboard.upcoming.map((item: any) => <div key={item.id} className="flex items-center gap-3 rounded-xl bg-secondary/45 p-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-card text-primary"><CalendarDays className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{item.label}</p><p className="text-[11px] text-muted-foreground">{item.type} · {shortDate(item.dueAt)}</p></div><span className="text-xs font-bold">{money(item.amountCents)}</span></div>) : <p className="py-8 text-sm text-muted-foreground">Sem compromissos próximos.</p>}</div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Pontos de atenção</p><h2 className="editorial-title mt-2 text-2xl">Leituras úteis</h2></div><Lightbulb className="h-5 w-5 text-amber-600" /></div><div className="mt-5 space-y-3">{dashboard.notifications.slice(0, 3).map((item: any) => <div className="rounded-xl border border-border/70 bg-card/50 p-3" key={item.id}><p className="text-xs font-bold">{item.title}</p><p className="mt-1 text-[11px] leading-4 text-muted-foreground">{item.body}</p></div>)}{!dashboard.notifications.length && <><div className="rounded-xl border border-amber-200/70 bg-amber-50/70 p-3 text-xs leading-5 text-amber-900 dark:border-amber-400/20 dark:bg-amber-400/10 dark:text-amber-100"><AlertTriangle className="mr-1 inline h-3.5 w-3.5" />Despesas fixas representam {summary.incomeCommitment}% da sua renda estimada.</div><div className="rounded-xl border border-emerald-200/70 bg-emerald-50/70 p-3 text-xs leading-5 text-emerald-900 dark:border-emerald-400/20 dark:bg-emerald-400/10 dark:text-emerald-100"><Target className="mr-1 inline h-3.5 w-3.5" />Mantenha os aportes recorrentes para avançar nas metas ativas.</div></>}</div></Panel></div><Panel className="mt-5 p-5 sm:p-6"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-[10px] uppercase font-extrabold tracking-[.18em] text-muted-foreground">Horizonte de 5 anos</p><h2 className="editorial-title mt-2 text-2xl">Trajetória do patrimônio</h2></div><div><p className="text-right text-xs text-muted-foreground">Estimativa ao final do período</p><p className="editorial-title text-right text-2xl">{money(dashboard.projection.at(-1)?.netWorthCents)}</p></div></div><div className="mt-5 h-[220px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={dashboard.projection.filter((_: any, index: number) => index % 5 === 4).map((item: any) => ({ month: `${item.month}m`, patrimônio: item.netWorthCents / 100 }))}><defs><linearGradient id="wealthGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#7d68aa" stopOpacity={.45} /><stop offset="100%" stopColor="#7d68aa" stopOpacity={.02} /></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="currentColor" opacity={.08} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 10 }} /><YAxis hide /><Tooltip formatter={(value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Area type="monotone" dataKey="patrimônio" stroke="#7864A8" strokeWidth={2.5} fill="url(#wealthGradient)" /></AreaChart></ResponsiveContainer></div></Panel></div>;
}

function TransactionsPage({ dashboard }: { dashboard: any }) {
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const utils = trpc.useUtils();
  const remove = trpc.finance.transactions.delete.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Lançamento excluído."); }, onError: error => toast.error(error.message) });
  const categories = new Map<number, any>(dashboard.categories.map((item: any) => [item.id, item]));
  const accounts = new Map<number, any>(dashboard.accounts.map((item: any) => [item.id, item]));
  const rows = dashboard.transactions.filter((item: any) => (filter === "all" || item.type === filter) && `${item.description} ${categories.get(item.categoryId)?.name ?? ""}`.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR")));
  return <div><PageHeading eyebrow="Organização" title="Lançamentos" description="Cada registro movimenta a conta vinculada e atualiza saldo, orçamento, projeções e relatórios." action={<TransactionDialog dashboard={dashboard} onDone={() => undefined} />} /><Panel className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-border/70 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full sm:max-w-sm"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={event => setSearch(event.target.value)} className="pl-9 bg-card/50" placeholder="Buscar por descrição ou categoria" /></div><Select value={filter} onValueChange={setFilter}><SelectTrigger className="w-full sm:w-40 bg-card/50"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos</SelectItem><SelectItem value="income">Receitas</SelectItem><SelectItem value="expense">Despesas</SelectItem></SelectContent></Select></div><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Movimento</TableHead><TableHead>Conta</TableHead><TableHead>Data</TableHead><TableHead>Status</TableHead><TableHead className="text-right">Valor</TableHead><TableHead className="w-24" /></TableRow></TableHeader><TableBody>{rows.length ? rows.map((item: any) => <TableRow key={item.id}><TableCell><div className="flex items-center gap-3"><span className={`grid h-8 w-8 place-items-center rounded-lg ${item.type === "income" ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300" : "bg-rose-100 text-rose-700 dark:bg-rose-400/10 dark:text-rose-300"}`}>{item.type === "income" ? <ArrowUpRight className="h-4 w-4" /> : <ArrowDownRight className="h-4 w-4" />}</span><div><p className="text-sm font-bold">{item.description}</p><p className="text-xs text-muted-foreground">{categories.get(item.categoryId)?.name ?? "Sem categoria"}</p></div></div></TableCell><TableCell className="text-sm text-muted-foreground">{accounts.get(item.accountId)?.name ?? "—"}</TableCell><TableCell className="text-sm">{shortDate(item.occurredAt)}</TableCell><TableCell><Badge variant="outline" className="font-medium">{statusLabel[item.paymentStatus]}</Badge></TableCell><TableCell className={`text-right text-sm font-extrabold ${item.type === "income" ? "text-emerald-700 dark:text-emerald-300" : "text-foreground"}`}>{item.type === "income" ? "+" : "−"}{money(item.amountCents)}</TableCell><TableCell><div className="flex justify-end gap-1"><TransactionDialog dashboard={dashboard} transaction={item} onDone={() => undefined} /><Button variant="ghost" size="icon" className="h-8 w-8 text-destructive" onClick={() => { if (window.confirm("Excluir este lançamento?")) remove.mutate({ id: item.id }); }}><Trash2 className="h-3.5 w-3.5" /></Button></div></TableCell></TableRow>) : <TableRow><TableCell colSpan={6} className="h-48 text-center text-sm text-muted-foreground">Nenhum lançamento encontrado. Adicione um movimento para começar.</TableCell></TableRow>}</TableBody></Table></div></Panel></div>;
}

function BudgetDialog({ dashboard }: { dashboard: any }) {
  const monthKey = new Date().toISOString().slice(0, 7);
  const [open, setOpen] = useState(false); const [categoryId, setCategoryId] = useState(""); const [amount, setAmount] = useState("");
  const utils = trpc.useUtils(); const upsert = trpc.finance.budgets.upsert.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Orçamento salvo."); setOpen(false); }, onError: error => toast.error(error.message) });
  const expenseCategories = dashboard.categories.filter((item: any) => item.type === "expense");
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Definir orçamento</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!categoryId || centsFromInput(amount) <= 0) return toast.error("Selecione uma categoria e informe um limite."); upsert.mutate({ categoryId: Number(categoryId), monthKey, limitCents: centsFromInput(amount) }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Novo orçamento</DialogTitle><DialogDescription>Defina um limite mensal por categoria.</DialogDescription></DialogHeader><div className="grid gap-4 py-6"><div className="grid gap-2"><Label>Categoria</Label><Select value={categoryId} onValueChange={setCategoryId}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{expenseCategories.map((item: any) => <SelectItem value={String(item.id)} key={item.id}>{item.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Limite no mês (R$)</Label><Input type="number" min="0" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={upsert.isPending}>Salvar orçamento</Button></DialogFooter></form></DialogContent></Dialog>;
}

function BudgetsPage({ dashboard }: { dashboard: any }) {
  return <div><PageHeading eyebrow="Planejamento" title="Orçamentos" description="Acompanhe o que foi realizado contra os limites que você definiu para este mês." action={<BudgetDialog dashboard={dashboard} />} /><div className="grid gap-4 lg:grid-cols-2">{dashboard.budgetProgress.length ? dashboard.budgetProgress.map((item: any) => { const warning = item.progress >= 100 ? "text-rose-700 bg-rose-100 dark:bg-rose-400/10 dark:text-rose-300" : item.progress >= 80 ? "text-amber-700 bg-amber-100 dark:bg-amber-400/10 dark:text-amber-300" : "text-emerald-700 bg-emerald-100 dark:bg-emerald-400/10 dark:text-emerald-300"; return <Panel className="p-5" key={item.id}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: item.color }} /><div><h2 className="text-sm font-bold">{item.categoryName}</h2><p className="mt-1 text-xs text-muted-foreground">{money(item.spentCents)} de {money(item.limitCents)}</p></div></div><Badge className={`${warning} border-0`}>{item.progress}%</Badge></div><Progress className="mt-5 h-2.5" value={Math.min(item.progress, 100)} /><div className="mt-3 flex justify-between text-xs text-muted-foreground"><span>{item.progress >= 80 ? "Atenção ao limite" : "Dentro do planejado"}</span><span>{money(Math.max(item.limitCents - item.spentCents, 0))} disponível</span></div></Panel>; }) : <div className="lg:col-span-2"><EmptyState onDemo={() => undefined} onOpenSettings={() => undefined} /></div>}</div><Panel className="mt-5 p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-2xl bg-amber-100 text-amber-700 dark:bg-amber-400/10 dark:text-amber-300"><Lightbulb className="h-4 w-4" /></span><p className="text-sm leading-6 text-muted-foreground">Quando um orçamento ultrapassa 80%, a aplicação cria um ponto de atenção para você avaliar o ritmo de gastos. Os avisos são leituras orientativas, não aconselhamento financeiro profissional.</p></div></Panel></div>;
}

function GoalsPage({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [target, setTarget] = useState(""); const [current, setCurrent] = useState(""); const [monthly, setMonthly] = useState(""); const [deadline, setDeadline] = useState("");
  const utils = trpc.useUtils(); const create = trpc.finance.goals.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Meta criada."); }, onError: error => toast.error(error.message) });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!name.trim() || centsFromInput(target) <= 0) return toast.error("Informe um nome e um valor-alvo."); create.mutate({ name, targetCents: centsFromInput(target), currentCents: centsFromInput(current), monthlyContributionCents: centsFromInput(monthly), targetDate: deadline ? new Date(`${deadline}T12:00:00`) : null, accountId: null, color: "#7864A8" }); };
  return <div><PageHeading eyebrow="Planejamento" title="Metas financeiras" description="Transforme intenções em marcos com progresso visível, aportes planejados e um prazo de referência." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Nova meta</Button></DialogTrigger><DialogContent><form onSubmit={submit}><DialogHeader><DialogTitle className="editorial-title text-3xl">Criar meta</DialogTitle><DialogDescription>Os aportes mensais entram nas projeções financeiras.</DialogDescription></DialogHeader><div className="grid gap-4 py-6 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><Label>Nome da meta</Label><Input value={name} onChange={event => setName(event.target.value)} placeholder="Ex.: Reserva de emergência" /></div><div className="grid gap-2"><Label>Valor-alvo (R$)</Label><Input type="number" min="0" step="0.01" value={target} onChange={event => setTarget(event.target.value)} /></div><div className="grid gap-2"><Label>Já acumulado (R$)</Label><Input type="number" min="0" step="0.01" value={current} onChange={event => setCurrent(event.target.value)} /></div><div className="grid gap-2"><Label>Aporte mensal (R$)</Label><Input type="number" min="0" step="0.01" value={monthly} onChange={event => setMonthly(event.target.value)} /></div><div className="grid gap-2"><Label>Data desejada</Label><Input type="date" value={deadline} onChange={event => setDeadline(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={create.isPending}>Criar meta</Button></DialogFooter></form></DialogContent></Dialog>} /><div className="grid gap-5 lg:grid-cols-2">{dashboard.goals.length ? dashboard.goals.map((goal: any) => { const progress = Math.min(100, Math.round(goal.currentCents / goal.targetCents * 100)); const monthDifference = goal.targetDate ? Math.max(1, (new Date(goal.targetDate).getFullYear() - new Date().getFullYear()) * 12 + new Date(goal.targetDate).getMonth() - new Date().getMonth()) : 0; const required = monthDifference ? Math.ceil(Math.max(0, goal.targetCents - goal.currentCents) / monthDifference) : goal.monthlyContributionCents; return <Panel className="p-6" key={goal.id}><div className="flex justify-between gap-4"><div><span className="inline-block h-2.5 w-2.5 rounded-full" style={{ backgroundColor: goal.color }} /><h2 className="editorial-title mt-4 text-3xl">{goal.name}</h2><p className="mt-2 text-sm text-muted-foreground">Prazo desejado: {goal.targetDate ? shortDate(goal.targetDate) : "sem data definida"}</p></div><Badge variant="outline" className="h-fit">{statusLabel[goal.status]}</Badge></div><div className="mt-8 flex items-end justify-between"><p className="editorial-title text-3xl">{money(goal.currentCents)}</p><p className="mb-1 text-xs text-muted-foreground">de {money(goal.targetCents)}</p></div><Progress className="mt-3 h-3" value={progress} /><div className="mt-3 flex justify-between text-xs"><span className="font-bold text-foreground">{progress}% concluída</span><span className="text-muted-foreground">Aporte: {money(goal.monthlyContributionCents)}/mês</span></div><div className="mt-6 rounded-xl bg-secondary/55 p-4 text-xs leading-5 text-muted-foreground">Para alcançar essa meta no prazo indicado, o aporte estimado é de <strong className="text-foreground">{money(required)} por mês</strong>.</div></Panel>; }) : <div className="lg:col-span-2"><EmptyState onDemo={() => undefined} onOpenSettings={() => undefined} /></div>}</div></div>;
}

function CardsPage({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [limit, setLimit] = useState(""); const [closingDay, setClosingDay] = useState("20"); const [dueDay, setDueDay] = useState("28");
  const utils = trpc.useUtils(); const create = trpc.finance.cards.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Cartão adicionado."); }, onError: error => toast.error(error.message) });
  return <div><PageHeading eyebrow="Compromissos" title="Cartões e faturas" description="Visualize limites, faturas abertas e parcelas que terão impacto nos seus próximos meses." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Adicionar cartão</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!name || centsFromInput(limit) <= 0) return toast.error("Informe nome e limite do cartão."); create.mutate({ name, brand: null, limitCents: centsFromInput(limit), closingDay: Number(closingDay), dueDay: Number(dueDay), paymentAccountId: null, color: "#5B477F" }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Novo cartão</DialogTitle><DialogDescription>As faturas e compras parceladas serão associadas a este cartão.</DialogDescription></DialogHeader><div className="grid gap-4 py-6 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><Label>Nome</Label><Input value={name} onChange={event => setName(event.target.value)} placeholder="Ex.: Cartão principal" /></div><div className="grid gap-2"><Label>Limite (R$)</Label><Input type="number" min="0" step="0.01" value={limit} onChange={event => setLimit(event.target.value)} /></div><div className="grid gap-2"><Label>Fechamento</Label><Input type="number" min="1" max="31" value={closingDay} onChange={event => setClosingDay(event.target.value)} /></div><div className="grid gap-2"><Label>Vencimento</Label><Input type="number" min="1" max="31" value={dueDay} onChange={event => setDueDay(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={create.isPending}>Adicionar cartão</Button></DialogFooter></form></DialogContent></Dialog>} /><div className="grid gap-5 lg:grid-cols-2">{dashboard.cards.length ? dashboard.cards.map((card: any) => { const invoices = dashboard.invoices.filter((invoice: any) => invoice.cardId === card.id && invoice.status !== "paid"); const openCents = invoices.reduce((sum: number, invoice: any) => sum + invoice.totalCents, 0); const installments = dashboard.installments.filter((item: any) => item.cardId === card.id); return <Panel className="overflow-hidden p-0" key={card.id}><div className="p-6 text-white" style={{ background: `linear-gradient(135deg, ${card.color}, #342847)` }}><div className="flex justify-between"><CreditCard className="h-6 w-6" /><span className="text-xs tracking-[.15em] font-bold">{card.brand ?? "CRÉDITO"}</span></div><p className="mt-12 text-sm opacity-70">{card.name}</p><p className="mt-2 font-mono text-xl tracking-[.2em]">•••• •••• ••••</p><div className="mt-7 flex justify-between text-xs"><span>Fecha dia {card.closingDay}</span><span>Vence dia {card.dueDay}</span></div></div><div className="p-6"><div className="flex justify-between text-sm"><span className="text-muted-foreground">Limite disponível</span><strong>{money(card.limitCents - openCents)}</strong></div><Progress className="mt-2 h-2" value={Math.min(100, openCents / card.limitCents * 100)} /><div className="mt-5 rounded-xl bg-secondary/45 p-4"><div className="flex justify-between"><span className="text-xs text-muted-foreground">Fatura atual</span><span className="text-sm font-extrabold">{money(openCents)}</span></div>{invoices[0] && <p className="mt-1 text-[11px] text-muted-foreground">Vencimento: {shortDate(invoices[0].dueAt)}</p>}</div>{installments.length > 0 && <p className="mt-4 text-xs text-muted-foreground">{installments.length} compra(s) parcelada(s) com impacto futuro.</p>}</div></Panel>; }) : <div className="lg:col-span-2"><EmptyState onDemo={() => undefined} onOpenSettings={() => undefined} /></div>}</div>{dashboard.installments.length > 0 && <Panel className="mt-5 overflow-hidden"><div className="border-b p-5"><h2 className="editorial-title text-2xl">Parcelas futuras</h2></div><div className="divide-y divide-border/60">{dashboard.installments.map((item: any) => <div className="flex items-center justify-between gap-3 p-4" key={item.id}><div><p className="text-sm font-bold">{item.description}</p><p className="text-xs text-muted-foreground">Parcela {item.currentInstallment} de {item.totalInstallments}</p></div><span className="text-sm font-bold">{money(item.installmentCents)}/mês</span></div>)}</div></Panel>}</div>;
}

function DebtsPage({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [creditor, setCreditor] = useState(""); const [balance, setBalance] = useState(""); const [payment, setPayment] = useState(""); const [rate, setRate] = useState("0"); const [dueDay, setDueDay] = useState("10");
  const utils = trpc.useUtils(); const create = trpc.finance.debts.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Dívida registrada."); }, onError: error => toast.error(error.message) });
  return <div><PageHeading eyebrow="Compromissos" title="Dívidas" description="Registre saldos, juros e parcelas para enxergar o custo dos compromissos em sua projeção." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Adicionar dívida</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!creditor || centsFromInput(balance) <= 0 || centsFromInput(payment) <= 0) return toast.error("Preencha credor, saldo e parcela."); create.mutate({ creditor, originalCents: centsFromInput(balance), balanceCents: centsFromInput(balance), annualInterestRate: Number(rate), installmentsTotal: 1, monthlyPaymentCents: centsFromInput(payment), dueDay: Number(dueDay), accountId: null }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Nova dívida</DialogTitle><DialogDescription>Inclua os dados para calcular impacto e prazo estimado.</DialogDescription></DialogHeader><div className="grid gap-4 py-6 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><Label>Credor</Label><Input value={creditor} onChange={event => setCreditor(event.target.value)} /></div><div className="grid gap-2"><Label>Saldo devedor (R$)</Label><Input type="number" min="0" step="0.01" value={balance} onChange={event => setBalance(event.target.value)} /></div><div className="grid gap-2"><Label>Parcela mensal (R$)</Label><Input type="number" min="0" step="0.01" value={payment} onChange={event => setPayment(event.target.value)} /></div><div className="grid gap-2"><Label>Juros ao ano (%)</Label><Input type="number" min="0" step="0.1" value={rate} onChange={event => setRate(event.target.value)} /></div><div className="grid gap-2"><Label>Vencimento (dia)</Label><Input type="number" min="1" max="31" value={dueDay} onChange={event => setDueDay(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={create.isPending}>Registrar dívida</Button></DialogFooter></form></DialogContent></Dialog>} /><div className="grid gap-5 lg:grid-cols-2">{dashboard.debts.length ? dashboard.debts.map((debt: any) => { const months = Math.ceil(debt.balanceCents / Math.max(1, debt.monthlyPaymentCents)); const extraMonths = Math.ceil(debt.balanceCents / Math.max(1, debt.monthlyPaymentCents + 30000)); return <Panel className="p-6" key={debt.id}><div className="flex justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">{debt.status === "active" ? "Em andamento" : statusLabel[debt.status]}</p><h2 className="editorial-title mt-2 text-3xl">{debt.creditor}</h2></div><Landmark className="h-5 w-5 text-primary" /></div><div className="mt-8 grid grid-cols-2 gap-3"><div><p className="text-xs text-muted-foreground">Saldo devedor</p><p className="mt-1 text-xl font-extrabold">{money(debt.balanceCents)}</p></div><div><p className="text-xs text-muted-foreground">Parcela</p><p className="mt-1 text-xl font-extrabold">{money(debt.monthlyPaymentCents)}</p></div></div><div className="mt-6 border-t border-border/70 pt-4 text-xs text-muted-foreground"><p>Juros informados: <strong className="text-foreground">{debt.annualInterestRate}% ao ano</strong></p><p className="mt-2">No ritmo atual, a estimativa simples é de <strong className="text-foreground">{months} meses</strong>. Ao adicionar R$ 300/mês, seria de aproximadamente <strong className="text-foreground">{extraMonths} meses</strong>.</p></div></Panel>; }) : <div className="lg:col-span-2"><EmptyState onDemo={() => undefined} onOpenSettings={() => undefined} /></div>}</div></div>;
}

function AssetsPage({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [type, setType] = useState<"investment" | "property" | "vehicle" | "other">("investment"); const [value, setValue] = useState(""); const utils = trpc.useUtils(); const create = trpc.finance.assets.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Ativo adicionado."); }, onError: error => toast.error(error.message) });
  return <div><PageHeading eyebrow="Sua base" title="Patrimônio" description="O patrimônio líquido é calculado separando ativos de passivos: ativos menos dívidas e faturas em aberto." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Adicionar ativo</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!name || centsFromInput(value) <= 0) return toast.error("Informe nome e valor do ativo."); create.mutate({ name, type, valueCents: centsFromInput(value), updatedValueAt: new Date() }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Novo ativo</DialogTitle><DialogDescription>Registre investimentos, bens e outros valores patrimoniais.</DialogDescription></DialogHeader><div className="grid gap-4 py-6"><div className="grid gap-2"><Label>Nome</Label><Input value={name} onChange={event => setName(event.target.value)} /></div><div className="grid gap-2"><Label>Tipo</Label><Select value={type} onValueChange={value => setType(value as typeof type)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="investment">Investimento</SelectItem><SelectItem value="property">Imóvel</SelectItem><SelectItem value="vehicle">Veículo</SelectItem><SelectItem value="other">Outro ativo</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Valor atual (R$)</Label><Input type="number" min="0" step="0.01" value={value} onChange={event => setValue(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={create.isPending}>Salvar ativo</Button></DialogFooter></form></DialogContent></Dialog>} /><div className="grid gap-5 lg:grid-cols-3"><Panel className="p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Ativos</p><p className="editorial-title mt-3 text-4xl text-emerald-700 dark:text-emerald-300">{money(dashboard.summary.assetCents)}</p><p className="mt-2 text-xs text-muted-foreground">Contas, investimentos e bens</p></Panel><Panel className="p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Passivos</p><p className="editorial-title mt-3 text-4xl text-rose-700 dark:text-rose-300">{money(dashboard.summary.liabilityCents)}</p><p className="mt-2 text-xs text-muted-foreground">Cartões, empréstimos e dívidas</p></Panel><Panel className="p-6 bg-primary text-primary-foreground"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] opacity-70">Patrimônio líquido</p><p className="editorial-title mt-3 text-4xl">{money(dashboard.summary.netWorthCents)}</p><p className="mt-2 text-xs opacity-75">Ativos − passivos</p></Panel></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><Panel className="overflow-hidden"><div className="border-b border-border/70 p-5"><h2 className="editorial-title text-2xl">Contas e saldos</h2></div><div className="divide-y divide-border/60">{dashboard.accounts.map((account: any) => <div className="flex items-center justify-between p-4" key={account.id}><div className="flex items-center gap-3"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: account.color }} /><div><p className="text-sm font-bold">{account.name}</p><p className="text-xs text-muted-foreground">{account.type}</p></div></div><span className="text-sm font-bold">{money(account.balanceCents)}</span></div>)}</div></Panel><Panel className="overflow-hidden"><div className="border-b border-border/70 p-5"><h2 className="editorial-title text-2xl">Outros ativos</h2></div><div className="divide-y divide-border/60">{dashboard.assets.length ? dashboard.assets.map((asset: any) => <div className="flex items-center justify-between p-4" key={asset.id}><div><p className="text-sm font-bold">{asset.name}</p><p className="text-xs text-muted-foreground">{asset.type}</p></div><span className="text-sm font-bold">{money(asset.valueCents)}</span></div>) : <p className="p-7 text-sm text-muted-foreground">Nenhum ativo adicional registrado.</p>}</div></Panel></div></div>;
}

function ProjectionsPage({ dashboard }: { dashboard: any }) {
  const [horizon, setHorizon] = useState(24); const [incomeDelta, setIncomeDelta] = useState("0"); const [expenseDelta, setExpenseDelta] = useState("0"); const [contributionDelta, setContributionDelta] = useState("0"); const [purchase, setPurchase] = useState("0");
  const comparison = useMemo(() => dashboard.projection.slice(0, horizon).map((point: any, index: number) => { const monthlyImpact = centsFromInput(incomeDelta) - centsFromInput(expenseDelta) - centsFromInput(contributionDelta); const custom = point.netWorthCents + monthlyImpact * (index + 1) - (index === 0 ? centsFromInput(purchase) : 0); const conservative = point.netWorthCents - Math.round((point.expensesCents * .12) * (index + 1)); const optimistic = point.netWorthCents + Math.round((point.incomeCents * .08) * (index + 1)); return { month: `${point.month}m`, atual: point.netWorthCents / 100, conservador: conservative / 100, otimista: optimistic / 100, personalizado: custom / 100 }; }), [dashboard.projection, horizon, incomeDelta, expenseDelta, contributionDelta, purchase]);
  const last = comparison.at(-1);
  return <div><PageHeading eyebrow="Futuro financeiro" title="Projeções e “E se...?”" description="Compare hipóteses de forma orientativa. As projeções usam os dados registrados e premissas configuradas; não constituem aconselhamento financeiro profissional." /><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Panel className="p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Patrimônio projetado</p><h2 className="editorial-title mt-2 text-3xl">Cenários comparados</h2></div><Select value={String(horizon)} onValueChange={value => setHorizon(Number(value))}><SelectTrigger className="w-36 bg-card/60"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="6">6 meses</SelectItem><SelectItem value="12">1 ano</SelectItem><SelectItem value="24">2 anos</SelectItem><SelectItem value="60">5 anos</SelectItem></SelectContent></Select></div><div className="mt-6 h-[360px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={comparison}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="currentColor" opacity={.09} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><YAxis hide /><Tooltip formatter={(value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Legend wrapperStyle={{ fontSize: 11, paddingTop: 12 }} /><Line type="monotone" dataKey="atual" stroke="#7864A8" strokeWidth={2.5} dot={false} /><Line type="monotone" dataKey="conservador" stroke="#C48686" strokeWidth={1.8} strokeDasharray="6 4" dot={false} /><Line type="monotone" dataKey="otimista" stroke="#5B9C78" strokeWidth={1.8} strokeDasharray="6 4" dot={false} /><Line type="monotone" dataKey="personalizado" stroke="#D59551" strokeWidth={2.2} dot={false} /></LineChart></ResponsiveContainer></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><div className="rounded-xl bg-secondary/55 p-3"><p className="text-[10px] uppercase font-bold text-muted-foreground">Atual</p><p className="mt-1 text-sm font-extrabold">{money(Math.round((last?.atual ?? 0) * 100))}</p></div><div className="rounded-xl bg-rose-100/65 p-3 dark:bg-rose-400/10"><p className="text-[10px] uppercase font-bold text-muted-foreground">Conservador</p><p className="mt-1 text-sm font-extrabold">{money(Math.round((last?.conservador ?? 0) * 100))}</p></div><div className="rounded-xl bg-emerald-100/65 p-3 dark:bg-emerald-400/10"><p className="text-[10px] uppercase font-bold text-muted-foreground">Otimista</p><p className="mt-1 text-sm font-extrabold">{money(Math.round((last?.otimista ?? 0) * 100))}</p></div><div className="rounded-xl bg-amber-100/65 p-3 dark:bg-amber-400/10"><p className="text-[10px] uppercase font-bold text-muted-foreground">Seu cenário</p><p className="mt-1 text-sm font-extrabold">{money(Math.round((last?.personalizado ?? 0) * 100))}</p></div></div></Panel><Panel className="p-5 sm:p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Simulador</p><h2 className="editorial-title mt-2 text-3xl">Mude uma variável.</h2><p className="mt-2 text-xs leading-5 text-muted-foreground">O impacto é calculado na hora e comparado com a projeção atual.</p><div className="mt-6 space-y-4"><div className="grid gap-1.5"><Label className="text-xs">Aumentar renda mensal (R$)</Label><Input type="number" value={incomeDelta} onChange={event => setIncomeDelta(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Reduzir despesas mensais (R$)</Label><Input type="number" value={expenseDelta} onChange={event => setExpenseDelta(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Aporte adicional mensal (R$)</Label><Input type="number" value={contributionDelta} onChange={event => setContributionDelta(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Nova compra única (R$)</Label><Input type="number" value={purchase} onChange={event => setPurchase(event.target.value)} /></div></div><div className="mt-7 rounded-2xl border border-primary/15 bg-primary/5 p-4"><p className="text-xs leading-5 text-muted-foreground">A diferença estimada no cenário personalizado após {horizon} meses é de <strong className="text-foreground">{money(Math.round(((last?.personalizado ?? 0) - (last?.atual ?? 0)) * 100))}</strong>.</p></div></Panel></div></div>;
}

function CalendarPage({ dashboard }: { dashboard: any }) {
  const events = [...dashboard.upcoming, ...dashboard.recurrences.slice(0, 8).map((item: any) => ({ id: `recurrence-${item.id}`, label: item.description, dueAt: item.nextOccurrenceAt, amountCents: item.amountCents, type: item.type === "income" ? "Recebimento" : "Recorrência" }))].sort((a: any, b: any) => new Date(a.dueAt).getTime() - new Date(b.dueAt).getTime());
  return <div><PageHeading eyebrow="Agenda financeira" title="Calendário" description="Consulte pagamentos, recebimentos, faturas, recorrências e vencimentos em uma mesma linha do tempo." /><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Panel className="p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Este mês</p><h2 className="editorial-title mt-2 text-3xl">{new Date().toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}</h2><div className="mt-7 grid grid-cols-7 gap-1.5">{Array.from({ length: 35 }, (_, index) => { const day = index - new Date(new Date().getFullYear(), new Date().getMonth(), 1).getDay() + 1; const isToday = day === new Date().getDate(); const count = events.filter((event: any) => new Date(event.dueAt).getDate() === day).length; return <div key={index} className={`aspect-square rounded-xl p-1 text-center text-xs ${day < 1 || day > 31 ? "opacity-20" : isToday ? "bg-primary text-primary-foreground font-bold" : "bg-secondary/50"}`}><span>{day > 0 && day <= 31 ? day : ""}</span>{count > 0 && <i className={`mx-auto mt-1 block h-1 w-1 rounded-full ${isToday ? "bg-primary-foreground" : "bg-primary"}`} />}</div>; })}</div></Panel><Panel className="overflow-hidden"><div className="border-b border-border/70 p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Próximos compromissos</p><h2 className="editorial-title mt-2 text-3xl">O que está por vir</h2></div><div className="divide-y divide-border/60">{events.length ? events.map((event: any) => <div className="flex items-center gap-4 p-5" key={event.id}><div className="grid h-11 w-11 place-items-center rounded-2xl bg-primary/10 text-primary"><span className="text-xs font-extrabold">{new Date(event.dueAt).getDate()}</span></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{event.label}</p><p className="text-xs text-muted-foreground">{event.type} · {shortDate(event.dueAt)}</p></div><span className="text-sm font-bold">{money(event.amountCents)}</span></div>) : <p className="p-8 text-sm text-muted-foreground">Ainda não há compromissos cadastrados.</p>}</div></Panel></div></div>;
}

function ReportsPage({ dashboard }: { dashboard: any }) {
  const download = () => { const lines = ["Data,Descrição,Tipo,Valor,Status", ...dashboard.transactions.map((item: any) => `${new Date(item.occurredAt).toLocaleDateString("pt-BR")},"${item.description.replaceAll('"', '""')}",${item.type},${(item.amountCents / 100).toFixed(2)},${item.paymentStatus}`)]; const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" })); link.download = "clareza-financeira-lancamentos.csv"; link.click(); URL.revokeObjectURL(link.href); };
  return <div><PageHeading eyebrow="Leituras do período" title="Relatórios" description="Analise receita, despesas, compromissos e progresso financeiro a partir dos seus próprios lançamentos." action={<div className="flex gap-2"><Button variant="outline" className="rounded-xl bg-card/60" onClick={download}><Download className="mr-2 h-4 w-4" />CSV</Button><Button variant="outline" className="rounded-xl bg-card/60" onClick={() => window.print()}><Download className="mr-2 h-4 w-4" />Salvar em PDF</Button></div>} /><div className="grid gap-5 xl:grid-cols-2"><Panel className="p-5 sm:p-6"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Composição de gastos</p><h2 className="editorial-title mt-2 text-3xl">Por categoria</h2></div><div className="mt-5 h-[290px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={dashboard.categorySpend} layout="vertical"><CartesianGrid strokeDasharray="3 5" horizontal={false} stroke="currentColor" opacity={.09} /><XAxis type="number" hide /><YAxis type="category" dataKey="name" width={95} axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><Tooltip formatter={(value: number) => money(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Bar dataKey="amountCents" radius={[0, 7, 7, 0]}>{dashboard.categorySpend.map((item: any) => <Cell key={item.categoryId} fill={item.color} />)}</Bar></BarChart></ResponsiveContainer></div></Panel><Panel className="p-5 sm:p-6"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Trajetória mensal</p><h2 className="editorial-title mt-2 text-3xl">Receitas x despesas</h2></div><div className="mt-5 h-[290px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={dashboard.cashflow}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="currentColor" opacity={.09} /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><YAxis hide /><Tooltip formatter={(value: number) => money(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Legend wrapperStyle={{ fontSize: 11 }} /><Line type="monotone" dataKey="receitas" stroke="#5B9C78" strokeWidth={2.5} dot={false} /><Line type="monotone" dataKey="despesas" stroke="#C48686" strokeWidth={2.5} dot={false} /></LineChart></ResponsiveContainer></div></Panel></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><Metric label="Taxa de economia" value={`${dashboard.summary.savingsRate}%`} note="Receitas menos despesas no mês" kind="positive" icon={TrendingUp} /><Metric label="Renda comprometida" value={`${dashboard.summary.incomeCommitment}%`} note="Recorrências, dívidas e parcelas" kind="negative" icon={ReceiptText} /><Metric label="Metas ativas" value={String(dashboard.goals.filter((item: any) => item.status === "active").length)} note="Planos em andamento" icon={Target} /></div></div>;
}

function SettingsPage({ dashboard }: { dashboard: any }) {
  const [income, setIncome] = useState(inputMoney(dashboard.profile.monthlyIncomeCents)); const [growth, setGrowth] = useState(String(dashboard.profile.annualIncomeGrowthRate)); const [inflation, setInflation] = useState(String(dashboard.profile.annualInflationRate)); const [returnRate, setReturnRate] = useState(String(dashboard.profile.annualInvestmentReturnRate)); const [accountName, setAccountName] = useState(""); const [accountOpening, setAccountOpening] = useState("");
  const utils = trpc.useUtils(); const profile = trpc.finance.profile.update.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Premissas atualizadas."); }, onError: error => toast.error(error.message) }); const account = trpc.finance.accounts.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setAccountName(""); setAccountOpening(""); toast.success("Conta adicionada."); }, onError: error => toast.error(error.message) });
  return <div><PageHeading eyebrow="Preferências" title="Configurações" description="Defina as premissas que tornam suas projeções mais próximas da sua realidade e organize suas contas." /><div className="grid gap-5 xl:grid-cols-[1fr_.9fr]"><Panel className="p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Premissas financeiras</p><h2 className="editorial-title mt-2 text-3xl">Seu ponto de referência</h2><form className="mt-7 grid gap-4 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); profile.mutate({ monthlyIncomeCents: centsFromInput(income), annualIncomeGrowthRate: Number(growth), annualInflationRate: Number(inflation), annualInvestmentReturnRate: Number(returnRate), onboardingCompleted: true }); }}><div className="grid gap-2 sm:col-span-2"><Label>Renda mensal prevista (R$)</Label><Input type="number" min="0" step="0.01" value={income} onChange={event => setIncome(event.target.value)} /></div><div className="grid gap-2"><Label>Crescimento de renda (% a.a.)</Label><Input type="number" min="-50" max="100" value={growth} onChange={event => setGrowth(event.target.value)} /></div><div className="grid gap-2"><Label>Inflação estimada (% a.a.)</Label><Input type="number" min="0" max="100" value={inflation} onChange={event => setInflation(event.target.value)} /></div><div className="grid gap-2 sm:col-span-2"><Label>Rentabilidade estimada (% a.a.)</Label><Input type="number" min="-50" max="100" value={returnRate} onChange={event => setReturnRate(event.target.value)} /></div><div className="sm:col-span-2"><Button type="submit" disabled={profile.isPending} className="rounded-xl">Salvar premissas</Button></div></form></Panel><Panel className="p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Contas</p><h2 className="editorial-title mt-2 text-3xl">Onde o dinheiro está</h2><form className="mt-7 grid gap-3" onSubmit={event => { event.preventDefault(); if (!accountName || centsFromInput(accountOpening) < 0) return toast.error("Informe os dados da conta."); account.mutate({ name: accountName, type: "checking", color: "#7864A8", openingBalanceCents: centsFromInput(accountOpening) }); }}><div className="grid gap-2"><Label>Nome da conta</Label><Input value={accountName} onChange={event => setAccountName(event.target.value)} placeholder="Ex.: Conta principal" /></div><div className="grid gap-2"><Label>Saldo inicial (R$)</Label><Input type="number" min="0" step="0.01" value={accountOpening} onChange={event => setAccountOpening(event.target.value)} /></div><Button variant="outline" type="submit" disabled={account.isPending} className="mt-1 rounded-xl">Adicionar conta</Button></form><div className="mt-6 space-y-2">{dashboard.accounts.map((item: any) => <div className="flex items-center justify-between rounded-xl bg-secondary/45 p-3" key={item.id}><span className="text-sm font-bold">{item.name}</span><span className="text-sm">{money(item.balanceCents)}</span></div>)}</div></Panel></div><Panel className="mt-5 p-5"><div className="flex gap-3"><ShieldCheck className="mt-0.5 h-5 w-5 shrink-0 text-emerald-600" /><p className="text-sm leading-6 text-muted-foreground">Os registros são vinculados ao seu perfil autenticado. A plataforma usa procedimentos protegidos e filtros de propriedade para impedir a visualização e alteração de dados de outros usuários.</p></div></Panel></div>;
}

function CardOperations({ dashboard }: { dashboard: any }) {
  const [cardId, setCardId] = useState("");
  const [invoiceValue, setInvoiceValue] = useState("");
  const [invoiceDueAt, setInvoiceDueAt] = useState(todayInput());
  const [purchaseDescription, setPurchaseDescription] = useState("");
  const [installmentValue, setInstallmentValue] = useState("");
  const [installmentsTotal, setInstallmentsTotal] = useState("2");
  const [openInvoice, setOpenInvoice] = useState(false);
  const [openInstallment, setOpenInstallment] = useState(false);
  const utils = trpc.useUtils();
  const invoice = trpc.finance.cards.addInvoice.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpenInvoice(false); toast.success("Fatura registrada."); }, onError: error => toast.error(error.message) });
  const installment = trpc.finance.cards.addInstallment.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpenInstallment(false); toast.success("Compra parcelada registrada."); }, onError: error => toast.error(error.message) });
  if (!dashboard.cards.length) return null;
  const selectedCardId = Number(cardId || dashboard.cards[0].id);
  const month = todayInput().slice(0, 7);
  return <div className="mt-5 flex flex-wrap gap-2"><Dialog open={openInvoice} onOpenChange={setOpenInvoice}><DialogTrigger asChild><Button variant="outline" className="rounded-xl bg-card/60"><ReceiptText className="mr-2 h-4 w-4" />Registrar fatura</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (centsFromInput(invoiceValue) <= 0) return toast.error("Informe o valor da fatura."); invoice.mutate({ cardId: selectedCardId, referenceMonth: month, dueAt: new Date(`${invoiceDueAt}T12:00:00`), totalCents: centsFromInput(invoiceValue) }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Fatura do cartão</DialogTitle><DialogDescription>Essa fatura entra nos próximos vencimentos e no patrimônio líquido como passivo enquanto estiver aberta.</DialogDescription></DialogHeader><div className="grid gap-4 py-6"><div className="grid gap-2"><Label>Cartão</Label><Select value={cardId || String(dashboard.cards[0].id)} onValueChange={setCardId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{dashboard.cards.map((card: any) => <SelectItem key={card.id} value={String(card.id)}>{card.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Valor da fatura (R$)</Label><Input type="number" min="0" step="0.01" value={invoiceValue} onChange={event => setInvoiceValue(event.target.value)} /></div><div className="grid gap-2"><Label>Vencimento</Label><Input type="date" value={invoiceDueAt} onChange={event => setInvoiceDueAt(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={invoice.isPending}>Salvar fatura</Button></DialogFooter></form></DialogContent></Dialog><Dialog open={openInstallment} onOpenChange={setOpenInstallment}><DialogTrigger asChild><Button variant="outline" className="rounded-xl bg-card/60"><CreditCard className="mr-2 h-4 w-4" />Registrar parcelamento</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!purchaseDescription || centsFromInput(installmentValue) <= 0) return toast.error("Preencha a compra e o valor da parcela."); installment.mutate({ cardId: selectedCardId, description: purchaseDescription, installmentCents: centsFromInput(installmentValue), totalInstallments: Number(installmentsTotal), currentInstallment: 1, firstDueAt: new Date(`${invoiceDueAt}T12:00:00`) }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Compra parcelada</DialogTitle><DialogDescription>As parcelas futuras serão consideradas no fluxo de caixa projetado.</DialogDescription></DialogHeader><div className="grid gap-4 py-6"><div className="grid gap-2"><Label>Cartão</Label><Select value={cardId || String(dashboard.cards[0].id)} onValueChange={setCardId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{dashboard.cards.map((card: any) => <SelectItem key={card.id} value={String(card.id)}>{card.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Descrição da compra</Label><Input value={purchaseDescription} onChange={event => setPurchaseDescription(event.target.value)} placeholder="Ex.: Notebook" /></div><div className="grid grid-cols-2 gap-3"><div className="grid gap-2"><Label>Valor da parcela (R$)</Label><Input type="number" min="0" step="0.01" value={installmentValue} onChange={event => setInstallmentValue(event.target.value)} /></div><div className="grid gap-2"><Label>Número de parcelas</Label><Input type="number" min="2" max="120" value={installmentsTotal} onChange={event => setInstallmentsTotal(event.target.value)} /></div></div><div className="grid gap-2"><Label>1º vencimento</Label><Input type="date" value={invoiceDueAt} onChange={event => setInvoiceDueAt(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={installment.isPending}>Salvar parcelamento</Button></DialogFooter></form></DialogContent></Dialog></div>;
}

function InvoicePayments({ dashboard }: { dashboard: any }) {
  const utils = trpc.useUtils();
  const pay = trpc.finance.cards.payInvoice.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Fatura quitada e saída registrada na conta vinculada."); }, onError: error => toast.error(error.message) });
  const openInvoices = dashboard.invoices.filter((item: any) => item.status !== "paid");
  if (!openInvoices.length) return null;
  return <Panel className="mt-5 overflow-hidden"><div className="border-b border-border/70 p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Pagamento</p><h2 className="editorial-title mt-2 text-2xl">Faturas em aberto</h2></div><div className="divide-y divide-border/60">{openInvoices.map((invoice: any) => <div key={invoice.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold">{dashboard.cards.find((card: any) => card.id === invoice.cardId)?.name ?? "Cartão"}</p><p className="mt-1 text-xs text-muted-foreground">Vencimento em {shortDate(invoice.dueAt)}</p></div><div className="flex items-center gap-4"><strong className="text-sm">{money(invoice.totalCents)}</strong><Button size="sm" className="rounded-lg" disabled={pay.isPending} onClick={() => pay.mutate({ invoiceId: invoice.id })}>Marcar como paga</Button></div></div>)}</div></Panel>;
}

function CardsWorkspace({ dashboard }: { dashboard: any }) { return <><CardsPage dashboard={dashboard} /><CardOperations dashboard={dashboard} /><InvoicePayments dashboard={dashboard} /></>; }

function RecurrenceDialog({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [description, setDescription] = useState(""); const [amount, setAmount] = useState(""); const [type, setType] = useState<"income" | "expense">("expense"); const [frequency, setFrequency] = useState<"weekly" | "monthly" | "yearly">("monthly"); const [accountId, setAccountId] = useState("none"); const [categoryId, setCategoryId] = useState("none"); const [nextDate, setNextDate] = useState(todayInput());
  const utils = trpc.useUtils(); const create = trpc.finance.transactions.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Lançamento recorrente criado."); }, onError: error => toast.error(error.message) }); const categories = dashboard.categories.filter((item: any) => item.type === type);
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline" className="rounded-xl bg-card/60"><CalendarDays className="mr-2 h-4 w-4" />Novo recorrente</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!description || centsFromInput(amount) <= 0) return toast.error("Informe a descrição e o valor."); create.mutate({ description, amountCents: centsFromInput(amount), type, recurrenceFrequency: frequency, recurrenceEndAt: null, accountId: accountId === "none" ? null : Number(accountId), categoryId: categoryId === "none" ? null : Number(categoryId), occurredAt: new Date(`${nextDate}T12:00:00`), dueAt: new Date(`${nextDate}T12:00:00`), paymentStatus: "pending", paymentMethod: null, notes: null }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Lançamento recorrente</DialogTitle><DialogDescription>Ele será considerado em projeções e nos próximos compromissos.</DialogDescription></DialogHeader><div className="grid gap-4 py-6 sm:grid-cols-2"><div className="grid gap-2 sm:col-span-2"><Label>Descrição</Label><Input value={description} onChange={event => setDescription(event.target.value)} placeholder="Ex.: Internet" /></div><div className="grid gap-2"><Label>Tipo</Label><Select value={type} onValueChange={value => { setType(value as "income" | "expense"); setCategoryId("none"); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="income">Receita</SelectItem><SelectItem value="expense">Despesa</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Valor (R$)</Label><Input type="number" min="0" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} /></div><div className="grid gap-2"><Label>Frequência</Label><Select value={frequency} onValueChange={value => setFrequency(value as "weekly" | "monthly" | "yearly")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="weekly">Semanal</SelectItem><SelectItem value="monthly">Mensal</SelectItem><SelectItem value="yearly">Anual</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Próxima ocorrência</Label><Input type="date" value={nextDate} onChange={event => setNextDate(event.target.value)} /></div><div className="grid gap-2"><Label>Conta</Label><Select value={accountId} onValueChange={setAccountId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Sem conta vinculada</SelectItem>{dashboard.accounts.map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Categoria</Label><Select value={categoryId} onValueChange={setCategoryId}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">Sem categoria</SelectItem>{categories.map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></div></div><DialogFooter><Button type="submit" disabled={create.isPending}>Criar recorrência</Button></DialogFooter></form></DialogContent></Dialog>;
}

function TransactionsWorkspace({ dashboard }: { dashboard: any }) { return <><TransactionsPage dashboard={dashboard} /><div className="mt-5 flex flex-wrap gap-2"><RecurrenceDialog dashboard={dashboard} /></div>{dashboard.recurrences.length > 0 && <Panel className="mt-5 overflow-hidden"><div className="border-b border-border/70 p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Compromissos planejados</p><h2 className="editorial-title mt-2 text-2xl">Lançamentos recorrentes</h2></div><div className="divide-y divide-border/60">{dashboard.recurrences.map((item: any) => <div className="flex items-center justify-between gap-3 p-4" key={item.id}><div><p className="text-sm font-bold">{item.description}</p><p className="mt-1 text-xs text-muted-foreground">{item.frequency === "monthly" ? "Mensal" : item.frequency === "weekly" ? "Semanal" : "Anual"} · Próxima ocorrência em {shortDate(item.nextOccurrenceAt)}</p></div><span className="text-sm font-bold">{item.type === "income" ? "+" : "−"}{money(item.amountCents)}</span></div>)}</div></Panel>}</>; }

function ReportsPeriodPanel({ dashboard }: { dashboard: any }) {
  const [period, setPeriod] = useState("30"); const from = Date.now() - Number(period) * 86400000; const rows = dashboard.transactions.filter((item: any) => new Date(item.occurredAt).getTime() >= from); const income = rows.filter((item: any) => item.type === "income").reduce((sum: number, item: any) => sum + item.amountCents, 0); const expenses = rows.filter((item: any) => item.type === "expense").reduce((sum: number, item: any) => sum + item.amountCents, 0);
  return <Panel className="mt-5 p-5 sm:p-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Recorte analítico</p><h2 className="editorial-title mt-2 text-2xl">Leitura por período</h2></div><Select value={period} onValueChange={setPeriod}><SelectTrigger className="w-44 bg-card/60"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="30">Últimos 30 dias</SelectItem><SelectItem value="90">Últimos 3 meses</SelectItem><SelectItem value="365">Últimos 12 meses</SelectItem></SelectContent></Select></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-emerald-100/65 p-4 dark:bg-emerald-400/10"><p className="text-xs text-muted-foreground">Receitas no período</p><p className="mt-2 text-xl font-extrabold">{money(income)}</p></div><div className="rounded-xl bg-rose-100/65 p-4 dark:bg-rose-400/10"><p className="text-xs text-muted-foreground">Despesas no período</p><p className="mt-2 text-xl font-extrabold">{money(expenses)}</p></div><div className="rounded-xl bg-secondary/55 p-4"><p className="text-xs text-muted-foreground">Saldo do período</p><p className="mt-2 text-xl font-extrabold">{money(income - expenses)}</p></div></div></Panel>;
}

function ReportsWorkspace({ dashboard }: { dashboard: any }) { return <><ReportsPage dashboard={dashboard} /><ReportsPeriodPanel dashboard={dashboard} /></>; }

function FinancialOrganization({ dashboard }: { dashboard: any }) {
  const [categoryName, setCategoryName] = useState("");
  const [categoryType, setCategoryType] = useState<"income" | "expense">("expense");
  const [essential, setEssential] = useState(false);
  const utils = trpc.useUtils();
  const createCategory = trpc.finance.categories.create.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setCategoryName(""); toast.success("Categoria adicionada."); }, onError: error => toast.error(error.message) });
  const removeCategory = trpc.finance.categories.delete.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Categoria removida."); }, onError: error => toast.error(error.message) });
  const removeAccount = trpc.finance.accounts.delete.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); toast.success("Conta removida."); }, onError: error => toast.error(error.message) });
  return <Panel className="mt-5 p-5 sm:p-6"><div className="grid gap-8 xl:grid-cols-[.85fr_1.15fr]"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Categorias</p><h2 className="editorial-title mt-2 text-2xl">Classifique com clareza</h2><form className="mt-5 grid gap-3" onSubmit={event => { event.preventDefault(); if (!categoryName.trim()) return toast.error("Informe o nome da categoria."); createCategory.mutate({ name: categoryName.trim(), type: categoryType, color: categoryType === "income" ? "#4A9B75" : "#7864A8", essential }); }}><Input value={categoryName} onChange={event => setCategoryName(event.target.value)} placeholder="Ex.: Alimentação" /><div className="grid grid-cols-2 gap-3"><Select value={categoryType} onValueChange={value => setCategoryType(value as "income" | "expense")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="expense">Despesa</SelectItem><SelectItem value="income">Receita</SelectItem></SelectContent></Select><Button variant={essential ? "default" : "outline"} type="button" onClick={() => setEssential(current => !current)} className="rounded-xl">{essential ? "Essencial" : "Marcar essencial"}</Button></div><Button type="submit" disabled={createCategory.isPending} className="rounded-xl">Adicionar categoria</Button></form></div><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Sua organização</p><h2 className="editorial-title mt-2 text-2xl">Contas e categorias</h2><div className="mt-5 grid gap-4 md:grid-cols-2"><div><p className="mb-2 text-xs font-bold text-muted-foreground">Contas</p><div className="space-y-2">{dashboard.accounts.length ? dashboard.accounts.map((item: any) => <div className="flex items-center justify-between gap-2 rounded-xl bg-secondary/45 p-3" key={item.id}><div className="min-w-0"><p className="truncate text-xs font-bold">{item.name}</p><p className="text-[10px] text-muted-foreground">{money(item.balanceCents)}</p></div><Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => window.confirm("Remover esta conta?") && removeAccount.mutate({ id: item.id })}><Trash2 className="h-3.5 w-3.5" /></Button></div>) : <p className="text-xs text-muted-foreground">Nenhuma conta criada.</p>}</div></div><div><p className="mb-2 text-xs font-bold text-muted-foreground">Categorias</p><div className="space-y-2">{dashboard.categories.length ? dashboard.categories.map((item: any) => <div className="flex items-center justify-between gap-2 rounded-xl bg-secondary/45 p-3" key={item.id}><div className="flex min-w-0 items-center gap-2"><i className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: item.color }} /><p className="truncate text-xs font-bold">{item.name}</p></div><Button size="icon" variant="ghost" className="h-7 w-7 text-destructive" onClick={() => window.confirm("Remover esta categoria?") && removeCategory.mutate({ id: item.id })}><Trash2 className="h-3.5 w-3.5" /></Button></div>) : <p className="text-xs text-muted-foreground">Nenhuma categoria criada.</p>}</div></div></div></div></div></Panel>;
}

function SettingsWorkspace({ dashboard }: { dashboard: any }) { return <><SettingsPage dashboard={dashboard} /><FinancialOrganization dashboard={dashboard} /></>; }

function GoalForecastDetails({ dashboard }: { dashboard: any }) {
  if (!dashboard.goals.length) return null;
  return <Panel className="mt-5 overflow-hidden"><div className="border-b border-border/70 p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Ritmo de evolução</p><h2 className="editorial-title mt-2 text-2xl">Estimativas de conclusão</h2></div><div className="divide-y divide-border/60">{dashboard.goals.map((goal: any) => { const forecast = dashboard.goalForecast.find((item: any) => item.goalId === goal.id); return <div key={goal.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold">{goal.name}</p><p className="mt-1 text-xs text-muted-foreground">Aporte atual: {money(goal.monthlyContributionCents)}/mês</p></div><div className="text-left sm:text-right"><p className="text-sm font-extrabold">{forecast?.estimatedCompletionAt ? shortDate(forecast.estimatedCompletionAt) : "Aporte não definido"}</p><p className="mt-1 text-xs text-muted-foreground">{forecast?.monthsToCompletion !== null ? `${forecast?.monthsToCompletion} meses no ritmo atual` : `Necessário: ${money(forecast?.requiredContributionCents)}/mês`}</p></div></div>; })}</div></Panel>;
}

function GoalContributionDialog({ dashboard }: { dashboard: any }) {
  const [open, setOpen] = useState(false); const [goalId, setGoalId] = useState(""); const [amount, setAmount] = useState(""); const utils = trpc.useUtils(); const contribution = trpc.finance.goals.addContribution.useMutation({ onSuccess: async () => { await utils.finance.dashboard.invalidate(); setOpen(false); toast.success("Aporte registrado na meta."); }, onError: error => toast.error(error.message) });
  if (!dashboard.goals.length) return null;
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline" className="mt-5 rounded-xl bg-card/60"><Plus className="mr-2 h-4 w-4" />Registrar aporte</Button></DialogTrigger><DialogContent><form onSubmit={event => { event.preventDefault(); if (!goalId || centsFromInput(amount) <= 0) return toast.error("Selecione uma meta e informe o aporte."); contribution.mutate({ id: Number(goalId), amountCents: centsFromInput(amount) }); }}><DialogHeader><DialogTitle className="editorial-title text-3xl">Aportar em uma meta</DialogTitle><DialogDescription>O valor será adicionado ao progresso da meta e atualizará sua estimativa de conclusão.</DialogDescription></DialogHeader><div className="grid gap-4 py-6"><div className="grid gap-2"><Label>Meta</Label><Select value={goalId} onValueChange={setGoalId}><SelectTrigger><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{dashboard.goals.filter((item: any) => item.status === "active").map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.name}</SelectItem>)}</SelectContent></Select></div><div className="grid gap-2"><Label>Valor do aporte (R$)</Label><Input type="number" min="0" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} /></div></div><DialogFooter><Button type="submit" disabled={contribution.isPending}>Registrar aporte</Button></DialogFooter></form></DialogContent></Dialog>;
}

function GoalsWorkspace({ dashboard }: { dashboard: any }) { return <><GoalsPage dashboard={dashboard} /><GoalContributionDialog dashboard={dashboard} /><GoalForecastDetails dashboard={dashboard} /></>; }

function DebtForecastDetails({ dashboard }: { dashboard: any }) {
  if (!dashboard.debts.length) return null;
  return <Panel className="mt-5 overflow-hidden"><div className="border-b border-border/70 p-5"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Simulação de amortização</p><h2 className="editorial-title mt-2 text-2xl">O efeito de acrescentar R$ 300</h2></div><div className="divide-y divide-border/60">{dashboard.debts.map((debt: any) => { const forecast = dashboard.debtForecast.find((item: any) => item.debtId === debt.id); const interestSaved = Math.max(0, (forecast?.regular?.interestCents ?? 0) - (forecast?.withExtra300?.interestCents ?? 0)); const monthsSaved = Math.max(0, (forecast?.regular?.months ?? 0) - (forecast?.withExtra300?.months ?? 0)); return <div className="grid gap-3 p-5 sm:grid-cols-[1fr_auto_auto] sm:items-center sm:gap-8" key={debt.id}><div><p className="text-sm font-bold">{debt.creditor}</p><p className="mt-1 text-xs text-muted-foreground">Parcela atual de {money(debt.monthlyPaymentCents)} · Juros de {debt.annualInterestRate}% ao ano</p></div><div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Prazo reduzido</p><p className="mt-1 text-lg font-extrabold text-emerald-700 dark:text-emerald-300">{monthsSaved} meses</p></div><div><p className="text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground">Juros estimados poupados</p><p className="mt-1 text-lg font-extrabold text-emerald-700 dark:text-emerald-300">{money(interestSaved)}</p></div></div>; })}</div></Panel>;
}

function DebtsWorkspace({ dashboard }: { dashboard: any }) { return <><DebtsPage dashboard={dashboard} /><DebtForecastDetails dashboard={dashboard} /></>; }

function CalendarWorkspace({ dashboard }: { dashboard: any }) {
  const milestones = dashboard.goals.filter((goal: any) => goal.targetDate).map((goal: any) => ({ id: `goal-${goal.id}`, label: goal.name, dueAt: goal.targetDate, amountCents: goal.targetCents, type: "Meta" }));
  return <><CalendarPage dashboard={{ ...dashboard, upcoming: [...dashboard.upcoming, ...milestones] }} /><Panel className="mt-5 p-5"><div className="flex gap-3"><Target className="mt-0.5 h-5 w-5 shrink-0 text-primary" /><p className="text-sm leading-6 text-muted-foreground">Os marcos de metas com prazo definido também aparecem no calendário, ao lado de faturas, recorrências, parcelas e outros vencimentos.</p></div></Panel></>;
}

function Onboarding({ onDemo }: { onDemo: () => void }) {
  const [step, setStep] = useState(1);
  const [income, setIncome] = useState("");
  const [reserve, setReserve] = useState("");
  const [goalName, setGoalName] = useState("");
  const [goalTarget, setGoalTarget] = useState("");
  const utils = trpc.useUtils();
  const profile = trpc.finance.profile.update.useMutation();
  const account = trpc.finance.accounts.create.useMutation();
  const goal = trpc.finance.goals.create.useMutation();
  const finish = async () => {
    if (centsFromInput(income) <= 0) { toast.error("Informe sua renda mensal para continuar."); return; }
    try {
      await profile.mutateAsync({ monthlyIncomeCents: centsFromInput(income), reserveCents: centsFromInput(reserve), annualIncomeGrowthRate: 0, annualInflationRate: 4, annualInvestmentReturnRate: 8, onboardingCompleted: true });
      if (centsFromInput(reserve) > 0) await account.mutateAsync({ name: "Reserva inicial", type: "savings", color: "#4A9B75", openingBalanceCents: centsFromInput(reserve) });
      if (goalName.trim() && centsFromInput(goalTarget) > 0) await goal.mutateAsync({ name: goalName.trim(), targetCents: centsFromInput(goalTarget), currentCents: centsFromInput(reserve), monthlyContributionCents: 0, accountId: null, targetDate: null, color: "#7864A8" });
      await utils.finance.dashboard.invalidate();
      toast.success("Seu ponto de partida foi registrado.");
    } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível concluir o onboarding."); }
  };
  const busy = profile.isPending || account.isPending || goal.isPending;
  return <div className="mx-auto max-w-4xl"><div className="mb-7 text-center"><p className="text-[10px] font-extrabold uppercase tracking-[.22em] text-primary">Primeiros passos</p><h1 className="editorial-title mt-3 text-4xl sm:text-5xl">Vamos desenhar seu ponto de partida.</h1><p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-muted-foreground">Bastam algumas referências para transformar a Clareza em uma visão que acompanha sua vida financeira.</p></div><Panel className="overflow-hidden"><div className="grid grid-cols-3 border-b border-border/60">{["Sua renda", "Sua reserva", "Seu horizonte"].map((label, index) => <div key={label} className={`p-4 text-center text-xs font-bold ${step === index + 1 ? "bg-primary text-primary-foreground" : "text-muted-foreground"}`}><span className="mr-2 opacity-70">0{index + 1}</span>{label}</div>)}</div><div className="p-7 sm:p-10">{step === 1 && <div className="mx-auto max-w-md"><Banknote className="h-6 w-6 text-primary" /><h2 className="editorial-title mt-5 text-3xl">Qual renda mensal serve como base?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Use um valor realista para que os indicadores e projeções tenham uma referência inicial.</p><div className="mt-7 grid gap-2"><Label>Renda mensal prevista (R$)</Label><Input type="number" min="0" step="0.01" value={income} onChange={event => setIncome(event.target.value)} placeholder="0,00" autoFocus /></div><div className="mt-8 flex justify-between"><Button variant="ghost" onClick={onDemo}>Explorar demonstração</Button><Button onClick={() => setStep(2)}>Continuar</Button></div></div>}{step === 2 && <div className="mx-auto max-w-md"><ShieldCheck className="h-6 w-6 text-emerald-600" /><h2 className="editorial-title mt-5 text-3xl">E quanto já está reservado?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Esse valor será registrado como uma conta de reserva, para acompanhar sua segurança financeira desde o início.</p><div className="mt-7 grid gap-2"><Label>Reserva disponível (R$)</Label><Input type="number" min="0" step="0.01" value={reserve} onChange={event => setReserve(event.target.value)} placeholder="0,00" /></div><div className="mt-8 flex justify-between"><Button variant="ghost" onClick={() => setStep(1)}>Voltar</Button><Button onClick={() => setStep(3)}>Continuar</Button></div></div>}{step === 3 && <div className="mx-auto max-w-md"><Target className="h-6 w-6 text-primary" /><h2 className="editorial-title mt-5 text-3xl">Que intenção quer tornar visível?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Você pode criar sua primeira meta agora ou avançar e organizar detalhes depois.</p><div className="mt-7 grid gap-4"><div className="grid gap-2"><Label>Nome da meta (opcional)</Label><Input value={goalName} onChange={event => setGoalName(event.target.value)} placeholder="Ex.: Reserva de emergência" /></div><div className="grid gap-2"><Label>Valor-alvo (R$, opcional)</Label><Input type="number" min="0" step="0.01" value={goalTarget} onChange={event => setGoalTarget(event.target.value)} placeholder="0,00" /></div></div><div className="mt-8 flex justify-between"><Button variant="ghost" onClick={() => setStep(2)}>Voltar</Button><Button onClick={finish} disabled={busy}>{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Ver minha Clareza</Button></div></div>}</div></Panel></div>;
}

function ProjectionSimulator({ dashboard }: { dashboard: any }) {
  const [months, setMonths] = useState(24);
  const [income, setIncome] = useState("0");
  const [expenses, setExpenses] = useState("0");
  const [contribution, setContribution] = useState("0");
  const [purchase, setPurchase] = useState("0");
  const [newDebt, setNewDebt] = useState("0");
  const [inflation, setInflation] = useState("0");
  const [investment, setInvestment] = useState("0");
  const [incomeGrowth, setIncomeGrowth] = useState("0");
  const [incomeLossMonths, setIncomeLossMonths] = useState("0");
  const input = useMemo(() => ({ months, incomeAdjustmentCents: centsFromInput(income), expenseAdjustmentCents: centsFromInput(expenses), monthlyContributionAdjustmentCents: centsFromInput(contribution), incomeGrowthAdjustmentRate: Number(incomeGrowth) || 0, inflationAdjustmentRate: Number(inflation) || 0, investmentReturnAdjustmentRate: Number(investment) || 0, oneOffPurchaseCents: centsFromInput(purchase), incomeLossMonths: Number(incomeLossMonths) || 0, newDebtPaymentCents: centsFromInput(newDebt) }), [months, income, expenses, contribution, incomeGrowth, inflation, investment, purchase, incomeLossMonths, newDebt]);
  const { data: scenarios, isLoading } = trpc.finance.scenarios.compare.useQuery(input);
  const chartData = scenarios?.atual.map((point: any, index: number) => ({ month: `${point.month}m`, atual: point.netWorthCents / 100, conservador: scenarios.conservador[index]?.netWorthCents / 100, otimista: scenarios.otimista[index]?.netWorthCents / 100, personalizado: scenarios.personalizado[index]?.netWorthCents / 100 })) ?? [];
  const final: any = chartData.at(-1);
  return <div><PageHeading eyebrow="Futuro financeiro" title="Projeções e “E se...?”" description="Compare hipóteses usando renda, despesas, inflação, investimentos, aportes, novas compras e compromissos. As estimativas são orientativas e não constituem aconselhamento financeiro profissional." /><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><Panel className="p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Patrimônio projetado</p><h2 className="editorial-title mt-2 text-3xl">Cenários comparados</h2></div><Select value={String(months)} onValueChange={value => setMonths(Number(value))}><SelectTrigger className="w-40 bg-card/60"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="3">3 meses</SelectItem><SelectItem value="6">6 meses</SelectItem><SelectItem value="12">1 ano</SelectItem><SelectItem value="24">2 anos</SelectItem><SelectItem value="60">5 anos</SelectItem><SelectItem value="120">10 anos</SelectItem></SelectContent></Select></div><div className="mt-6 h-[360px]">{isLoading ? <div className="grid h-full place-items-center text-sm text-muted-foreground"><Loader2 className="mb-3 h-5 w-5 animate-spin text-primary" />Atualizando cenários…</div> : <ResponsiveContainer width="100%" height="100%"><LineChart data={chartData}><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="currentColor" opacity={.09} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fontSize: 11 }} /><YAxis hide /><Tooltip formatter={(value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(value)} contentStyle={{ borderRadius: 14, border: "1px solid var(--border)", background: "var(--card)" }} /><Legend wrapperStyle={{ fontSize: 11, paddingTop: 12 }} /><Line type="monotone" dataKey="atual" stroke="#7864A8" strokeWidth={2.5} dot={false} /><Line type="monotone" dataKey="conservador" stroke="#C48686" strokeWidth={1.8} strokeDasharray="6 4" dot={false} /><Line type="monotone" dataKey="otimista" stroke="#5B9C78" strokeWidth={1.8} strokeDasharray="6 4" dot={false} /><Line type="monotone" dataKey="personalizado" stroke="#D59551" strokeWidth={2.2} dot={false} /></LineChart></ResponsiveContainer>}</div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Atual", "atual", "bg-secondary/55"], ["Conservador", "conservador", "bg-rose-100/65 dark:bg-rose-400/10"], ["Otimista", "otimista", "bg-emerald-100/65 dark:bg-emerald-400/10"], ["Personalizado", "personalizado", "bg-amber-100/65 dark:bg-amber-400/10"]].map(([label, key, color]) => <div key={key} className={`rounded-xl p-3 ${color}`}><p className="text-[10px] uppercase font-bold text-muted-foreground">{label}</p><p className="mt-1 text-sm font-extrabold">{money(Math.round(Number(final?.[key] ?? 0) * 100))}</p></div>)}</div></Panel><Panel className="p-5 sm:p-6"><p className="text-[10px] font-extrabold uppercase tracking-[.18em] text-muted-foreground">Simulador</p><h2 className="editorial-title mt-2 text-3xl">E se você mudar o rumo?</h2><div className="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-1"><div className="grid gap-1.5"><Label className="text-xs">Variação de renda mensal (R$)</Label><Input type="number" value={income} onChange={event => setIncome(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Variação de despesas (R$)</Label><Input type="number" value={expenses} onChange={event => setExpenses(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Aporte mensal adicional (R$)</Label><Input type="number" value={contribution} onChange={event => setContribution(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Nova compra única (R$)</Label><Input type="number" value={purchase} onChange={event => setPurchase(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Nova parcela mensal (R$)</Label><Input type="number" value={newDebt} onChange={event => setNewDebt(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Perda de renda (meses)</Label><Input type="number" min="0" max="24" value={incomeLossMonths} onChange={event => setIncomeLossMonths(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Variação da inflação (% a.a.)</Label><Input type="number" value={inflation} onChange={event => setInflation(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Variação dos investimentos (% a.a.)</Label><Input type="number" value={investment} onChange={event => setInvestment(event.target.value)} /></div><div className="grid gap-1.5"><Label className="text-xs">Variação de crescimento da renda (% a.a.)</Label><Input type="number" value={incomeGrowth} onChange={event => setIncomeGrowth(event.target.value)} /></div></div><div className="mt-6 rounded-2xl border border-primary/15 bg-primary/5 p-4"><p className="text-xs leading-5 text-muted-foreground">No cenário personalizado, a diferença projetada após {months} meses é de <strong className="text-foreground">{money(Math.round((Number(final?.personalizado ?? 0) - Number(final?.atual ?? 0)) * 100))}</strong>.</p></div></Panel></div></div>;
}

export default function FinanceWorkspace({ section }: { section: FinanceSection }) {
  const { data: dashboard, isLoading, error } = trpc.finance.dashboard.useQuery();
  const seedDemo = trpc.finance.seedDemo.useMutation({ onSuccess: () => { toast.success("Dados de demonstração adicionados."); window.location.reload(); }, onError: error => toast.error(error.message) });
  const [localSection, setLocalSection] = useState<FinanceSection | null>(null);
  const active = localSection ?? section;
  if (isLoading) return <div className="grid min-h-[65vh] place-items-center"><div className="text-center"><Loader2 className="mx-auto h-7 w-7 animate-spin text-primary" /><p className="mt-4 text-sm text-muted-foreground">Organizando sua visão financeira…</p></div></div>;
  if (error || !dashboard) return <Panel className="p-8"><p className="text-sm text-destructive">Não foi possível carregar seus dados agora. Atualize a página ou tente novamente em instantes.</p></Panel>;
  const demo = () => seedDemo.mutate();
  const settings = () => setLocalSection("settings");
  const hasData = dashboard.accounts.length + dashboard.transactions.length + dashboard.goals.length > 0;
  if (active === "dashboard" && !dashboard.profile.onboardingCompleted && !hasData) return <Onboarding onDemo={demo} />;
  if (active === "dashboard") return <DashboardPage dashboard={dashboard} onDemo={demo} onOpenSettings={settings} />;
  if (active === "transactions") return <TransactionsWorkspace dashboard={dashboard} />;
  if (active === "budgets") return <BudgetsPage dashboard={dashboard} />;
  if (active === "goals") return <GoalsWorkspace dashboard={dashboard} />;
  if (active === "cards") return <CardsWorkspace dashboard={dashboard} />;
  if (active === "debts") return <DebtsWorkspace dashboard={dashboard} />;
  if (active === "assets") return <AssetsPage dashboard={dashboard} />;
  if (active === "projections") return <ProjectionSimulator dashboard={dashboard} />;
  if (active === "calendar") return <CalendarWorkspace dashboard={dashboard} />;
  if (active === "reports") return <ReportsWorkspace dashboard={dashboard} />;
  return <SettingsWorkspace dashboard={dashboard} />;
}
